"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type KeyboardEvent,
  type ReactNode,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** One row of a drill menu. A row with `items` opens them as the next level instead of running. */
export interface DrillMenuItem {
  id: string;
  label: string;
  icon?: ReactNode;
  items?: DrillMenuItem[];
  onSelect?: () => void;
  disabled?: boolean;
}

/** Props for a drill menu. Pass `path` to control which level shows, or `defaultPath` to let it hold its own state. */
export type DrillMenuProps = Omit<ComponentPropsWithoutRef<"div">, "children" | "onSelect"> & {
  items: DrillMenuItem[];
  /** Names the top level for screen readers, for example "Account". */
  label: string;
  /** The ids of the open rows, from the top level down. An empty list shows the top level. */
  path?: string[];
  defaultPath?: string[];
  onPathChange?: (path: string[]) => void;
  /** Runs after a row without a submenu ran its own `onSelect`. */
  onSelect?: (item: DrillMenuItem) => void;
  /** Read before the level name on the back row, as in "Back from Appearance". */
  backLabel?: string;
};

// Damping 40 is 2 × √400: critically damped, so a level slides in and the panel resizes without overshoot.
const SLIDE: Transition = { type: "spring", stiffness: 400, damping: 40, mass: 1 };
const FADE: Transition = { duration: 0.15 };
const INSTANT: Transition = { duration: 0 };

const ROW =
  "flex min-h-11 w-full cursor-pointer touch-manipulation items-center gap-3 rounded-lg px-3 text-left text-sm text-foreground outline-none hover:bg-muted disabled:cursor-not-allowed disabled:opacity-50 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring motion-safe:transition-colors motion-safe:duration-150 sm:min-h-9";

function Chevron({ back = false }: { back?: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4 shrink-0 text-muted-foreground">
      <path d={back ? "m9.5 3.5-4.5 4.5 4.5 4.5" : "m6.5 3.5 4.5 4.5-4.5 4.5"} strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

/** Walks the tree along the path and stops at the first id that opens nothing. */
function resolve(items: DrillMenuItem[], path: string[]) {
  let level = items;
  let parent: DrillMenuItem | null = null;
  const valid: string[] = [];
  for (const id of path) {
    const next = level.find((item) => item.id === id);
    if (!next?.items?.length) break;
    parent = next;
    level = next.items;
    valid.push(id);
  }
  return { level, parent, valid };
}

function findLevel(panel: HTMLElement | null, key: string) {
  return [...(panel?.children ?? [])].find((node): node is HTMLElement => node instanceof HTMLElement && node.dataset.level === key);
}

/**
 * A menu whose rows can open a submenu in the same panel. The submenu slides
 * in from the right while the panel takes its height, so a deep menu never
 * covers more of the page than one level needs.
 */
export function DrillMenu({
  items,
  label,
  path,
  defaultPath = [],
  onPathChange,
  onSelect,
  backLabel = "Back from",
  className,
  onKeyDown,
  ...divProps
}: DrillMenuProps) {
  const [ownPath, setOwnPath] = useState(defaultPath);
  const { level, parent, valid } = resolve(items, path ?? ownPath);
  const levelKey = valid.join("/");
  // 1 while going deeper, -1 while going back: the levels slide the way the person moved.
  const [direction, setDirection] = useState(1);
  const [height, setHeight] = useState<number>();
  const [tabStop, setTabStop] = useState<string | null>(null);
  const reduceMotion = useReducedMotion();
  const panelRef = useRef<HTMLDivElement>(null);
  // Which row takes focus once the new level is in the page: its first row, or the row that was left.
  const focusAfterMove = useRef<string | "first" | null>(null);

  // The leaving level stays in the page while it slides out, so rows are read from the level that is current.
  const rows = () => [...(findLevel(panelRef.current, levelKey)?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]:not(:disabled)') ?? [])];

  const move = (next: string[], focus: string | "first") => {
    focusAfterMove.current = focus;
    setDirection(next.length > valid.length ? 1 : -1);
    if (path === undefined) setOwnPath(next);
    onPathChange?.(next);
  };

  const goBack = () => {
    if (parent) move(valid.slice(0, -1), parent.id);
  };

  useLayoutEffect(() => {
    // No measured height means no layout yet, so the panel keeps its natural size.
    setHeight(findLevel(panelRef.current, levelKey)?.offsetHeight || undefined);
  }, [levelKey, items]);

  useEffect(() => {
    const focus = focusAfterMove.current;
    focusAfterMove.current = null;
    if (!focus) return;
    const all = rows();
    // Going deeper lands on the first choice, below the back row. Going back lands on the row that was open.
    const target = focus === "first" ? all[parent ? 1 : 0] ?? all[0] : all.find((row) => row.dataset.id === focus);
    target?.focus({ preventScroll: true });
  });

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;
    const all = rows();
    const index = all.findIndex((row) => row === document.activeElement);
    const focusRow = (next: number) => {
      event.preventDefault();
      all[(next + all.length) % all.length]?.focus();
    };
    if (event.key === "ArrowDown") focusRow(index + 1);
    else if (event.key === "ArrowUp") focusRow(index - 1);
    else if (event.key === "Home") focusRow(0);
    else if (event.key === "End") focusRow(all.length - 1);
    else if (event.key === "ArrowRight") {
      const item = level.find((entry) => entry.id === all[index]?.dataset.id);
      if (item?.items?.length) {
        event.preventDefault();
        move([...valid, item.id], "first");
      }
    } else if ((event.key === "ArrowLeft" || event.key === "Escape") && parent) {
      // At the top level Escape is left alone, so a popover around the menu can still close on it.
      event.preventDefault();
      goBack();
    }
  };

  // One row holds the tab stop: the last one focused on this level, or else the first.
  const firstRow = parent ? "back" : level[0]?.id;
  const stop = level.some((item) => item.id === tabStop) || (tabStop === "back" && parent) ? tabStop : firstRow;
  const offset = (sign: number) => (reduceMotion ? { opacity: 0 } : { x: `${sign * 100}%`, opacity: 1 });

  return (
    <div
      {...divProps}
      onKeyDown={handleKeyDown}
      className={cn("w-full max-w-xs overflow-hidden rounded-xl border border-border bg-card", className)}
    >
      <motion.div
        ref={panelRef}
        initial={false}
        animate={height === undefined ? undefined : { height }}
        transition={reduceMotion ? INSTANT : SLIDE}
        className="relative"
      >
      <AnimatePresence mode="popLayout" initial={false} custom={direction}>
        <motion.div
          key={levelKey}
          data-level={levelKey}
          role="menu"
          aria-label={parent ? parent.label : label}
          custom={direction}
          variants={{
            enter: (sign: number) => offset(sign),
            center: { x: 0, opacity: 1 },
            exit: (sign: number) => offset(-sign),
          }}
          initial="enter"
          animate="center"
          exit="exit"
          transition={reduceMotion ? FADE : SLIDE}
          className="flex w-full flex-col p-1"
        >
          {parent ? (
            <button
              type="button"
              role="menuitem"
              data-id="back"
              tabIndex={stop === "back" ? 0 : -1}
              onFocus={() => setTabStop("back")}
              onClick={goBack}
              className={cn(ROW, "font-medium")}
            >
              <Chevron back />
              <span className="min-w-0 flex-1 truncate">
                <span className="sr-only">{backLabel} </span>
                {parent.label}
              </span>
            </button>
          ) : null}
          {level.map((item) => {
            const opens = Boolean(item.items?.length);
            return (
              <button
                key={item.id}
                type="button"
                role="menuitem"
                data-id={item.id}
                aria-haspopup={opens ? "menu" : undefined}
                disabled={item.disabled}
                tabIndex={stop === item.id ? 0 : -1}
                onFocus={() => setTabStop(item.id)}
                onClick={() => {
                  if (opens) return move([...valid, item.id], "first");
                  item.onSelect?.();
                  onSelect?.(item);
                }}
                className={ROW}
              >
                {item.icon ? (
                  <span aria-hidden="true" className="flex size-4 shrink-0 items-center justify-center text-muted-foreground">
                    {item.icon}
                  </span>
                ) : null}
                <span className="min-w-0 flex-1 truncate">{item.label}</span>
                {opens ? <Chevron /> : null}
              </button>
            );
          })}
        </motion.div>
      </AnimatePresence>
      </motion.div>
    </div>
  );
}
